/** Рублей за единицу книги: зарплаты в игре дают 2,67–3,67 ₽ за минуту (согласовано 31.10). */
export const ECONOMY_TABLE_RATE = 3

export const tablePrice = (units: number) => Math.max(1, Math.round(units * ECONOMY_TABLE_RATE))

